CREATE SET TABLE MDP01_META.META_ETL_JOB ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      etl_job_id INTEGER NOT NULL,      job_name VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      job_type VARCHAR(50) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      source_table_id INTEGER NOT NULL,      target_table_id INTEGER NOT NULL,      source_layer_id INTEGER NOT NULL,      target_layer_id INTEGER NOT NULL,      transformation_sql CLOB(16777216) CHARACTER SET UNICODE,      where_clause VARCHAR(2000) CHARACTER SET LATIN CASESPECIFIC,      primary_key_columns VARCHAR(500) CHARACTER SET LATIN CASESPECIFIC,      hash_columns VARCHAR(2000) CHARACTER SET LATIN CASESPECIFIC,      incremental_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      valid_from_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      valid_to_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      is_current_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      is_active CHAR(1) CHARACTER SET LATIN CASESPECIFIC DEFAULT 'Y',      execution_order INTEGER,      parallelism INTEGER DEFAULT 1 ,      batch_size INTEGER,      beschreibung VARCHAR(2000) CHARACTER SET LATIN CASESPECIFIC,      tags VARCHAR(500) CHARACTER SET LATIN CASESPECIFIC,      created_by VARCHAR(50) CHARACTER SET LATIN CASESPECIFIC,      create_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      modified_by VARCHAR(50) CHARACTER SET LATIN CASESPECIFIC,      last_alter_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      RETRY_COUNT INTEGER DEFAULT 3 ,      TIMEOUT_SECONDS INTEGER DEFAULT 3600 )PRIMARY INDEX ( etl_job_id )UNIQUE INDEX ( job_name );